param([Parameter(Mandatory = $true)][string]$Target)

$ErrorActionPreference = 'Stop'

function Get-Value([string]$Name, [string]$Default = '') {
    $value = [Environment]::GetEnvironmentVariable($Name)
    if ($null -eq $value) { return $Default }
    return $value
}

function TomlQuote([string]$Value) {
    if ($null -eq $Value) { $Value = '' }
    $Value = $Value.Replace('\', '\\').Replace('"', '\"')
    $Value = $Value.Replace("`r", '\r').Replace("`n", '\n').Replace("`t", '\t')
    return '"' + $Value + '"'
}

function ReadExistingSecret([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '' }
    foreach ($line in [IO.File]::ReadAllLines($Path)) {
        $match = [regex]::Match($line, '^\s*shared_secret\s*=\s*"([0-9A-Fa-f]+)"\s*$')
        if ($match.Success) { return $match.Groups[1].Value }
    }
    return ''
}

function NewRandomSecret() {
    $bytes = New-Object byte[] 32
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    try { $rng.GetBytes($bytes) } finally { $rng.Dispose() }
    return (($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
}

function ResolveSecret([string]$PanelValue, [string]$ExistingValue) {
    $value = $PanelValue.Trim()
    $placeholder = '^(?i)(change-me.*|paste.*secret.*|shared[-_ ]?secret|your[-_ ]?secret|replace[-_ ]?me.*)$'
    if ($value -match $placeholder) { throw 'The shared secret is a documented placeholder, not a usable secret' }
    if ($value -ne '') { return $value }
    if ($ExistingValue -ne '') { return $ExistingValue }
    return NewRandomSecret
}

function ParseBool([string]$Value, [string]$Name) {
    switch ($Value.Trim().ToLowerInvariant()) {
        'true' { return 'true' }
        'false' { return 'false' }
        default { throw "$Name must be true or false" }
    }
}

function ParsePort([string]$Value, [string]$Name) {
    $port = 0
    if (-not [int]::TryParse($Value, [ref]$port) -or $port -lt 1 -or $port -gt 65535) { throw "$Name must be from 1 through 65535" }
    return $port
}

function WriteAtomic([string]$Path, [string]$Content) {
    $directory = Split-Path -Parent $Path
    if ($directory -and -not (Test-Path -LiteralPath $directory)) { New-Item -ItemType Directory -Path $directory -Force | Out-Null }
    $temporary = Join-Path $directory ('.' + [IO.Path]::GetFileName($Path) + '.' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [IO.File]::WriteAllText($temporary, $Content, (New-Object Text.UTF8Encoding $false))
        Move-Item -LiteralPath $temporary -Destination $Path -Force
    }
    finally {
        if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force }
    }
}

$bindAddress = Get-Value 'NR_BIND_ADDRESS' '0.0.0.0'
$registryPort = ParsePort (Get-Value 'NR_REGISTRY_PORT' '8765') 'Registry port'
$publicPort = ParsePort (Get-Value 'NR_PUBLIC_PORT' '42420') 'Proxy public port'
$advertise = ParseBool (Get-Value 'NR_ADVERTISE' 'false') 'Master-server advertising'
$hasPassword = ParseBool (Get-Value 'NR_HAS_PASSWORD' 'false') 'Password listing flag'
$whitelisted = ParseBool (Get-Value 'NR_WHITELISTED' 'false') 'Whitelist listing flag'
$publicHost = (Get-Value 'NR_PUBLIC_HOST' '').Trim()
$gameVersion = (Get-Value 'NR_GAME_VERSION' '1.22.6').Trim()
if ($advertise -eq 'true') {
    if ($publicHost -eq '') { throw 'Advertising requires the public hostname or IP of Nimbus Proxy' }
    if ($gameVersion -eq '') { throw 'Advertising requires the Vintage Story game version supported by the selected Stratum release' }
}
$secret = ResolveSecret (Get-Value 'NR_SHARED_SECRET' '') (ReadExistingSecret $Target)

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add('bind_url = ' + (TomlQuote "http://${bindAddress}:$registryPort"))
$lines.Add('shared_secret = ' + (TomlQuote $secret))
$lines.Add('accepted_secrets = []')
$lines.Add('backend_stale_seconds = 20')
$lines.Add('backend_drop_seconds = 120')
$lines.Add('nonce_window_seconds = 90')
$lines.Add('max_reservation_ttl_seconds = 300')
$lines.Add('log_heartbeats = false')
$lines.Add('state_dir = "."')
$lines.Add('')
$lines.Add('[api_tokens]')
$lines.Add('enabled = false')
$lines.Add('rate_limit_per_minute = 60')
$lines.Add('trust_forwarded_proto = false')
$lines.Add('')
$lines.Add('[identity]')
$lines.Add('advertise_on_master_server = ' + $advertise)
$lines.Add('master_server_url = "http://masterserver.vintagestory.at/api/v1/servers/"')
$lines.Add('public_host = ' + (TomlQuote $publicHost))
$lines.Add('public_port = ' + $publicPort)
$lines.Add('server_name = ' + (TomlQuote (Get-Value 'NR_SERVER_NAME' 'Nimbus Network')))
$lines.Add('server_description = ' + (TomlQuote (Get-Value 'NR_SERVER_DESCRIPTION' '')))
$lines.Add('server_url = ""')
$lines.Add('server_icon = ""')
$lines.Add('vh_identifier = ""')
$lines.Add('game_version = ' + (TomlQuote $gameVersion))
$lines.Add('max_players_override = 0')
$lines.Add('mod_source = "aggregate"')
$lines.Add('explicit_mods = []')
$lines.Add('whitelisted = ' + $whitelisted)
$lines.Add('has_password = ' + $hasPassword)
$lines.Add('heartbeat_interval_seconds = 120')
$lines.Add('')
$lines.Add('[identity.playstyle]')
$lines.Add('id = "surviveandbuild"')
$lines.Add('lang_code = "preset-surviveandbuild"')

WriteAtomic $Target (($lines -join "`n") + "`n")
Write-Output "wrote $Target"
